Oto przykładowa implementacja BFS w języku C++ z wykorzystaniem listy sąsiedztwa do reprezentowania grafu:

```
#include <iostream>
#include <queue>
#include <vector>

using namespace std;

void bfs(vector<vector<int>>& graph, int start) {
int n = graph.size();
vector<bool> visited(n, false);
queue<int> q;
q.push(start);
visited[start] = true;

while (!q.empty()) {
int node = q.front();
q.pop();

// Zrób coś z wierzchołkiem (np. wydrukuj)
cout << node << " ";

for (int neighbor : graph[node]) {
if (!visited[neighbor]) {
q.push(neighbor);
visited[neighbor] = true;
}
}
}
}

int main() {
int n, m; // n = liczba wierzchołków, m = liczba krawędzi
cin >> n >> m;

// Buduj graf
vector<vector<int>> graph(n);
for (int i = 0; i < m; i++) {
int a, b;
cin >> a >> b;
// Dodaj krawędź od a do b
graph[a].push_back(b);
// Dodaj krawędź od b do a, jeśli graf jest nieskierowany
// graph[b].push_back(a);
}

// Wykonaj BFS zaczynając od wierzchołka 0
bfs(graph, 0);

return 0;
}
```

Ta implementacja pobiera od użytkownika `n` (liczbę wierzchołków) i `m` (liczbę krawędzi), buduje listę sąsiedztwa reprezentującą graf i wykonuje BFS zaczynając od wierzchołka 0. Podczas BFS wierzchołki są drukowane w kolejności ich odwiedzenia.

