import java.util.Scanner;

public class Main {
public static void main(String[] args) {
Scanner sc = new Scanner(System.in);
int n = sc.nextInt(); // liczba par

for (int i = 0; i < n; i++) {
int a = sc.nextInt();
int b = sc.nextInt();
int sumSquared = (a + b) * (a + b);
int squaredSum = a * a + b * b;

if (sumSquared < squaredSum) {
System.out.println("<");
} else if (sumSquared > squaredSum) {
System.out.println(">");
} else {
System.out.println("=");
}
}
