Oto przykładowa implementacja algorytmu odległości Levenshteina w języku C++:

```
#include <iostream>
#include <algorithm>
#include <string>

using namespace std;

int odleglosc_levenshteina(string s1, string s2) {
const int m = s1.size();
const int n = s2.size();
int dp[m + 1][n + 1];

for (int i = 0; i <= m; i++) {
dp[i][0] = i;
}

for (int j = 0; j <= n; j++) {
dp[0][j] = j;
}

for (int i = 1; i <= m; i++) {
for (int j = 1; j <= n; j++) {
dp[i][j] = min({dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (s1[i - 1] != s2[j - 1])});
}
}

return dp[m][n];
}

int main() {
string s1 = "kitten";
string s2 = "sitting";
cout << "Odległość Levenshteina między " << s1 << " a " << s2 << " wynosi " << odleglosc_levenshteina(s1, s2) << endl;
return 0;
}
```

Ta implementacja oblicza odległość Levenshteina między dwoma wejściowymi ciągami `s1` i `s2`. Najpierw inicjalizuje tablicę programowania dynamicznego `dp` z przypadkami bazowymi dla pustych ciągów, a następnie wypełnia tablicę, iterując przez ciągi i porównując każdą parę znaków. Ostateczna wartość w tabeli to minimalna odległość Levenshteina między dwoma ciągami.

