```
#include <iostream>
#include <chrono>

unsigned long long seed = std::chrono::system_clock::now().time_since_epoch().count(); // Ziarno oparte na bieżącym czasie
unsigned long long a = 6364136223846793005;
unsigned long long c = 1442695040888963407;
unsigned long long m = 0x7fffffffffffffff; // Największa liczba pierwsza 64-bitowa

unsigned long long rand() {
seed = (a * seed + c) % m;
return seed;
}

int main() {
for (int i = 0; i < 10; i++) {
std::cout << rand() << std::endl;
}
return 0;
}
```

Generuje to sekwencję 64-bitowych liczb całkowitych przy użyciu wzoru `seed = (a * seed + c) % m`. Wartości `a`, `c` i `m` zostały dobrane w celu zapewnienia dobrych właściwości losowości. Początkowe ziarno jest ustawiane na podstawie bieżącego czasu, więc powinieneś otrzymać różną sekwencję liczb za każdym razem, gdy uruchomisz program.

