#include<stdio.h>
#include<stdbool.h>

// Funkcja do wyszukiwania dopasowania między danym ciągiem znaków a wzorcem
bool stringMatching(char string[], char pattern[]) 
{ 
// Oblicz długość danego ciągu znaków
int n = strlen(string); 

// Oblicz długość wzorca 
int m = strlen(pattern); 

// Indeksy ciągu znaków i wzorca 
int i = 0, j = 0; 

// Pętla zachłanna do dopasowania 
while(i < n && j < m) { 
if(string[i] == pattern[j]) { 
i++; 
j++; 
} 
// Przejdź o jedną pozycję wstecz w ciągu znaków
else { 
i = i - j + 1; 
j = 0; 
} 
} 

// Sprawdź, czy wzorzec został znaleziony czy nie
if(j == m) 
return true; 

return false; 
} 

// Kod sterujący 
int main() 
{ 
char string[] = "ababcab"; 
char pattern[] = "cab"; 

bool flag = stringMatching(string, pattern); 

if (flag) 
printf("Wzorzec pasuje"); 
else
printf("Wzorzec nie pasuje"); 

return 0; 
}

