```
<!DOCTYPE html>
<html>
<head>
<title>Animowana Piłka</title>
<style>
body {
margin: 0;
padding: 0;
overflow: hidden;
}
canvas {
display: block;
}
</style>
</head>
<body>
<canvas id="canvas"></canvas>

<script>
// pobierz element canvas z DOM
var canvas = document.getElementById("canvas");

// ustaw wymiary i pozycję canvas
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
canvas.style.position = "absolute";

// pobierz kontekst canvas do rysowania
var ctx = canvas.getContext("2d");

// zainicjuj pozycję i prędkość piłki
var x = 0;
var y = canvas.height / 2;
var vx = 5;

// zdefiniuj pętlę animacji
function animate() {
// wyczyść canvas
ctx.clearRect(0, 0, canvas.width, canvas.height);

// narysuj piłkę
ctx.beginPath();
ctx.arc(x, y, 20, 0, Math.PI*2, false);
ctx.fillStyle = "red";
ctx.fill();

// zaktualizuj pozycję piłki
x += vx;

// jeśli piłka dotrze do krawędzi canvas, zmień kierunek
if (x < 0 || x > canvas.width) {
vx = -vx;
}

// żądaj kolejnej klatki animacji
requestAnimationFrame(animate);
}

// rozpocznij pętlę animacji
animate();
</script>
</body>
</html>
```

