```cpp
#include <vector>
#include <utility>

using namespace std;

pair<double, double> linearRegression(vector<pair<double, double>> points) {
double n = points.size();
double sum_x = 0.0, sum_y = 0.0, sum_x2 = 0.0, sum_xy = 0.0;
for (auto p : points) {
sum_x += p.first;
sum_y += p.second;
sum_x2 += p.first * p.first;
sum_xy += p.first * p.second;
}
double slope = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x);
double intercept = (sum_y - slope * sum_x) / n;
return {slope, intercept};
}
```

Funkcja przyjmuje wektor par, reprezentujących punkty dwuwymiarowe. Następnie przechodzi przez każdy punkt, sumując wartości x, y, kwadraty wartości x oraz iloczyny x i y. Następnie obliczane są współczynniki nachylenia i przecięcia regresji liniowej za pomocą tych sum, a następnie zwracane są jako para.

