```
#include <cctype>
#include <string>

bool isPalindrome(std::string s) {
std::string cleanStr = "";
// Konwersja na małe litery i usunięcie znaków niealfanumerycznych
for (char c : s) {
if (std::isalnum(c)) {
cleanStr += std::tolower(c);
}
}
// Sprawdzenie, czy jest palindromem
int left = 0, right = cleanStr.size() - 1;
while (left <= right) {
if (cleanStr[left++] != cleanStr[right--])
return false;
}
return true;
}
